CREATE TABLE assets.model_catalog(organization_id text NOT NULL,site_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),snapshot jsonb NOT NULL CHECK(octet_length(snapshot::text)<=131072),PRIMARY KEY(organization_id,site_id),FOREIGN KEY(organization_id,site_id) REFERENCES platform_core.sites(organization_id,site_id));
