CREATE TABLE oip.canonical_asset_links(organization_id text NOT NULL,site_id text NOT NULL,source_id text NOT NULL,import_id uuid NOT NULL,source_record_number integer NOT NULL,asset_id text,mapping_id text,mapping_revision integer NOT NULL CHECK(mapping_revision>=0),state text NOT NULL CHECK(state IN ('mapped','pending','ambiguous','rejected','unmapped')),revision_key text NOT NULL,snapshot jsonb NOT NULL CHECK(octet_length(snapshot::text)<=65536),PRIMARY KEY(organization_id,site_id,source_id,import_id,source_record_number),FOREIGN KEY(organization_id,site_id,source_id,import_id,source_record_number) REFERENCES oip.facts(organization_id,site_id,source_id,import_id,source_record_number),FOREIGN KEY(organization_id,site_id,asset_id) REFERENCES assets.records(organization_id,site_id,id),FOREIGN KEY(organization_id,site_id,mapping_id,mapping_revision) REFERENCES assets.source_mapping_revisions(organization_id,site_id,mapping_id,revision),CHECK((state='mapped')=(asset_id IS NOT NULL)));
